export const findQuizSet = id => quizSets.find(set => set.id === id);
export const quizCategories = [...new Set(quizSets.map(set => set.category))];
// Four answer shapes keep one engine and one translation pipeline: every type stores
// its readable items in `options`. `truefalse` fixes the two labels, `multi` marks
// several correct indices and `order` lists the options in their canonical sequence
// (correct: null) so the runner can shuffle them per attempt.
const q=(id,d,topic,text,options,correct,why,figure)=>({id,d,type:'choice',topic,text,options,correct,why,...(figure?{figure}:{})});
const tf=(id,d,topic,text,correct,why,figure)=>({id,d,type:'truefalse',topic,text,options:['Doğru','Yanlış'],correct,why,...(figure?{figure}:{})});
const multi=(id,d,topic,text,options,correct,why,figure)=>({id,d,type:'multi',topic,text,options,correct,why,...(figure?{figure}:{})});
const order=(id,d,topic,text,options,why,figure)=>({id,d,type:'order',topic,text,options,correct:null,why,...(figure?{figure}:{})});
